{"cards": [{"node_code": "N_af70356208cd0b20", "definition": "研究脊髓结构损伤、炎症、退变及肿瘤等导致的运动、感觉及自主神经功能障碍的神经病学分支。", "boundary": "涵盖脊髓外伤、脊髓炎、脊髓空洞症、脊髓血管病及脊髓肿瘤等。区分于周围神经病（侧重神经根以下）、中枢神经系统感染（侧重脑实质或脑膜）及神经肌肉疾病（侧重肌肉或神经肌肉接头）。", "includes": ["脊髓外伤与脊髓损伤后管理", "脊髓炎、脊髓血管病及脊髓肿瘤", "脊髓空洞症及脊髓退行性变"], "excludes": ["主要累及脑实质的中枢神经系统感染（主挂中枢神经系统感染与周围神经病）", "以肌肉病变为主的神经肌肉疾病（主挂神经肌肉疾病）"], "sibling_distinctions": [{"other_code": "N_dd507807b8779743", "rule": "本节点侧重脊髓本身的病变；兄弟节点侧重脑实质、脑膜感染及周围神经病变。"}, {"other_code": "N_d3b72eda06d215a3", "rule": "本节点侧重脊髓传导束病变；兄弟节点侧重肌肉、神经肌肉接头及周围神经病变。"}], "cross_boundary_rule": "脊髓病变若由全身性感染引起，需结合感染病学；若涉及脊髓手术，可关联神经外科学，但疾病机制主挂本节点。"}, {"node_code": "N_ed19490a473727c4", "definition": "研究脑部及颈部血管病变导致的缺血性或出血性脑损伤、诊断、治疗及康复的神经病学分支。", "boundary": "涵盖脑梗死、脑出血、蛛网膜下腔出血、短暂性脑缺血发作及脑血管畸形等。区分于神经退行性疾病（侧重神经元丢失）及神经系统急危重症（侧重多系统危象管理）。", "includes": ["缺血性脑血管病（脑梗死、TIA）", "出血性脑血管病（脑出血、蛛网膜下腔出血）", "脑血管畸形及血管炎"], "excludes": ["非血管性脑损伤（如脑外伤、脑肿瘤）（主挂神经外科学或相关节点）", "以认知障碍为主的神经退行性疾病（主挂神经退行性疾病）"], "sibling_distinctions": [{"other_code": "N_f7c43bf10bc581af", "rule": "本节点侧重脑血管病本身的诊疗；兄弟节点侧重多系统危象的紧急综合管理。"}, {"other_code": "N_f75f7d8c87ba339f", "rule": "本节点侧重血管源性脑损伤；兄弟节点侧重神经元退变与丢失。"}], "cross_boundary_rule": "脑血管病急性期若出现严重生命体征不稳，需结合急危重症管理；若需介入或开颅手术，可关联神经外科学。"}, {"node_code": "N_c40ec59607d58fa1", "definition": "研究以神经纤维髓鞘脱失为主要病理特征的神经系统疾病，包括免疫介导及遗传性脱髓鞘病。", "boundary": "涵盖多发性硬化、视神经脊髓炎谱系疾病、急性播散性脑脊髓炎及遗传性周围神经脱髓鞘病。区分于神经免疫病（侧重非脱髓鞘性免疫机制）及周围神经疾病（侧重轴索病变）。", "includes": ["多发性硬化及视神经脊髓炎谱系疾病", "急性播散性脑脊髓炎", "遗传性周围神经脱髓鞘病"], "excludes": ["以轴索损伤为主的周围神经病（主挂周围神经疾病）", "非脱髓鞘机制的神经免疫病（主发作性与神经免疫病）"], "sibling_distinctions": [{"other_code": "N_39852d944b97e0c7", "rule": "本节点侧重髓鞘脱失病理；兄弟节点侧重癫痫发作机制及非脱髓鞘性免疫病。"}, {"other_code": "N_7697f4fdd43d2cd5", "rule": "本节点侧重髓鞘病变；兄弟节点侧重轴索、神经根及神经肌肉接头病变。"}], "cross_boundary_rule": "脱髓鞘疾病若伴随癫痫发作，需结合发作性神经病管理；若涉及免疫治疗，可关联免疫学，但疾病分类主挂本节点。"}]}
